CREATE FUNCTION pg_temp.id(k text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$ SELECT ('01900000-0000-7000-8000-0000000000' || lpad(k, 2, '0'))::uuid $$;
CREATE FUNCTION pg_temp.cl(p_type text, p_sub text, p_mem text DEFAULT NULL) RETURNS text LANGUAGE sql AS $$
  SELECT jsonb_strip_nulls(jsonb_build_object('actor_type', p_type, 'tenant_id', pg_temp.id('01'), 'sub', pg_temp.id(p_sub), 'membership_id', pg_temp.id(p_mem)))::text $$;
-- run p_sql as p_role with p_claims; mode n = row count of a query, w = ROW_COUNT of a statement; errors -> 'E' || SQLSTATE
CREATE FUNCTION pg_temp.x(p_role text, p_claims text, p_sql text, p_mode text) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE r text; n bigint;
BEGIN
  PERFORM set_config('request.jwt.claims', coalesce(p_claims, ''), true);
  EXECUTE format('SET LOCAL ROLE %I', p_role);
  BEGIN
    IF p_mode = 'n' THEN EXECUTE 'SELECT count(*) FROM (' || p_sql || ') t' INTO n; ELSE EXECUTE p_sql; GET DIAGNOSTICS n = ROW_COUNT; END IF;
    r := 'n=' || n;
  EXCEPTION WHEN OTHERS THEN r := 'E' || SQLSTATE;
  END;
  RESET ROLE;
  PERFORM set_config('request.jwt.claims', '', true);
  RETURN r;
END $f$;
-- expected outcome of a write: 0 rows when p_role holds the privilege (RLS filters), else 42501
CREATE FUNCTION pg_temp.want(p_role text, p_tbl regclass, p_priv text, p_col text DEFAULT NULL) RETURNS text LANGUAGE sql AS $$
  SELECT CASE WHEN (CASE WHEN p_col IS NULL THEN has_table_privilege(p_role, p_tbl, p_priv) ELSE has_column_privilege(p_role, p_tbl, p_col, p_priv) END)
              THEN 'n=0' ELSE 'E42501' END $$;
-- the tenant column (tenant_id, or id on the root table) and the column a probe UPDATE touches
CREATE FUNCTION pg_temp.tcol(p_tbl regclass) RETURNS text LANGUAGE sql AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = p_tbl AND attname = 'tenant_id' AND NOT attisdropped) THEN 'tenant_id' ELSE 'id' END $$;
CREATE FUNCTION pg_temp.ucol(p_tbl regclass) RETURNS text LANGUAGE sql AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = p_tbl AND attname = 'updated_at' AND NOT attisdropped) THEN 'updated_at' ELSE pg_temp.tcol(p_tbl) END $$;
CREATE FUNCTION pg_temp.owncol(p_tbl regclass) RETURNS text LANGUAGE sql AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = p_tbl AND attname = 'actor_id' AND NOT attisdropped) THEN 'actor_id' ELSE 'created_by' END $$;
-- row count of a query as the calling (super)user: step-1 preconditions, so a probe fails instead of passing on an empty table
CREATE FUNCTION pg_temp.n(p_sql text) RETURNS bigint LANGUAGE plpgsql AS $f$
DECLARE n bigint; BEGIN EXECUTE 'SELECT count(*) FROM (' || p_sql || ') t' INTO n; RETURN n; END $f$;
CREATE FUNCTION pg_temp.q(p_fmt text, p_tbl regclass) RETURNS text LANGUAGE sql AS $$
  SELECT format(p_fmt, p_tbl, pg_temp.tcol(p_tbl), pg_temp.ucol(p_tbl)) $$;
-- step 6: one INSERT per composite FK that carries the tenant column: a copy of a tenant-A row of T whose other FK columns point at a
-- tenant-B parent row (read from pg_constraint). stmt is NULL when no tenant-A row of T or no tenant-B parent row exists.
CREATE FUNCTION pg_temp.fk_probes(p_tbl regclass) RETURNS TABLE (conname text, stmt text) LANGUAGE plpgsql AS $f$
DECLARE k record; tc text := pg_temp.tcol(p_tbl); ptc text; arow jsonb; prow jsonb; patch jsonb; cols text;
BEGIN
  EXECUTE format('SELECT to_jsonb(t) FROM %s t WHERE %I = %L LIMIT 1', p_tbl, tc, pg_temp.id('01')) INTO arow;
  SELECT string_agg(quote_ident(attname), ', ' ORDER BY attnum) INTO cols FROM pg_attribute
   WHERE attrelid = p_tbl AND attnum > 0 AND NOT attisdropped AND attgenerated = '' AND attidentity <> 'a';
  FOR k IN SELECT c.conname::text AS conname, c.confrelid::regclass AS parent,
                  array(SELECT a.attname::text FROM unnest(c.conkey) WITH ORDINALITY u(n, o) JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = u.n ORDER BY u.o) AS ccols,
                  array(SELECT a.attname::text FROM unnest(c.confkey) WITH ORDINALITY u(n, o) JOIN pg_attribute a ON a.attrelid = c.confrelid AND a.attnum = u.n ORDER BY u.o) AS pcols
             FROM pg_constraint c WHERE c.conrelid = p_tbl AND c.contype = 'f' AND cardinality(c.conkey) > 1 ORDER BY c.conname LOOP
    CONTINUE WHEN NOT tc = ANY (k.ccols);
    ptc := k.pcols[array_position(k.ccols, tc)];
    EXECUTE format('SELECT to_jsonb(p) FROM %s p WHERE %I = %L LIMIT 1', k.parent, ptc, pg_temp.id('02')) INTO prow;
    conname := k.conname; stmt := NULL;
    IF arow IS NOT NULL AND prow IS NOT NULL THEN
      patch := '{}';
      FOR i IN 1 .. cardinality(k.ccols) LOOP
        IF k.ccols[i] <> tc THEN patch := patch || jsonb_build_object(k.ccols[i], prow -> k.pcols[i]); END IF;
      END LOOP;
      IF arow ? 'id' AND NOT patch ? 'id' THEN patch := patch || jsonb_build_object('id', gen_random_uuid()); END IF;
      stmt := format('INSERT INTO %s (%s) SELECT %s FROM jsonb_populate_record(NULL::%s, %L::jsonb)', p_tbl, cols, cols, p_tbl, arow || patch);
    END IF;
    RETURN NEXT;
  END LOOP;
END $f$;

-- INSERT of a copy of the first row of p_tbl matching p_where (read as the superuser), so only RLS can refuse it (no NOT NULL noise)
CREATE FUNCTION pg_temp.copy(p_tbl regclass, p_where text) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE r jsonb; cols text;
BEGIN
  EXECUTE format('SELECT to_jsonb(t) FROM %s t WHERE %s LIMIT 1', p_tbl, p_where) INTO r;
  IF r ? 'id' THEN r := r || jsonb_build_object('id', gen_random_uuid()); END IF;   -- no PK collision with the source row
  SELECT string_agg(quote_ident(attname), ', ' ORDER BY attnum) INTO cols FROM pg_attribute
   WHERE attrelid = p_tbl AND attnum > 0 AND NOT attisdropped AND attgenerated = '' AND attidentity <> 'a';
  RETURN format('INSERT INTO %s (%s) SELECT %s FROM jsonb_populate_record(NULL::%s, %L::jsonb)', p_tbl, cols, cols, p_tbl, r);
END $f$;
-- step 6 runner: the rows of p_tbl are removed first (superuser, replica mode, inside a rolled-back subtransaction) so a
-- natural-key UNIQUE collision with the copied row cannot mask the composite-FK check; returns pg_temp.x's result.
CREATE FUNCTION pg_temp.fk_try(p_tbl regclass, p_stmt text) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE r text;
BEGIN
  BEGIN
    SET LOCAL session_replication_role = replica;
    EXECUTE format('DELETE FROM %s', p_tbl);   -- both tenants: some natural keys are global (e.g. memberships__user_id__p_uq)
    SET LOCAL session_replication_role = origin;
    r := pg_temp.x('lims_api', pg_temp.cl('user', '32', '42'), p_stmt, 'w');
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'probe_rollback';
  EXCEPTION WHEN raise_exception THEN NULL;
  END;
  RETURN r;
END $f$;

